Describe 'install.ps1' {
    BeforeAll {
        # Every case that lets the installer run shadows Invoke-RestMethod with
        # a function that throws. Command resolution prefers functions over
        # cmdlets, so the first network call fails with this sentinel and
        # nothing is downloaded. Cases that need it run in a child process of
        # the same shell, so the Windows PowerShell 5.1 and pwsh CI steps each
        # test their own host; the child's own `exit 7` is the proof that the
        # installer did not terminate the session.
        function Invoke-InstallerChild {
